import numpy as np, json
from collections import Counter
def solve(g):
    g=np.array(g); h,w=g.shape
    cand=[]
    for r in range(h):
        if len(np.unique(g[r,:]))==1 and sum(Counter(g[r,:]).values())[0]==w: cand.append(('h',r))
    for c in range(w):
        if len(np.unique(g[:,c]))==1 and sum(Counter(g[:,c]).values())[0]==h: cand.append(('v',c))
    t,r=cand[0]
    # choose smaller region as A (or first region)
    if t=='h': A=g[:r]; B=g[r+1:]
    else: A=g[:,:r]; B=g[:,r+1:]
    oh,ow=A.shape; bh,bw=B.shape
    cnta=Counter(A.flatten()); cntb=Counter(B.flatten())
    nA=max(cnta,key=lambda k:cnta[k]) ; nB=max(cntb,key=lambda k:cntb[k])
    out=np.zeros((oh,ow),int)
    if t=='h':
        for rr in range(oh):
            for cc in range(ow):
                if A[rr,cc]!=nA and B[bh-1-rr,cc]!=nB: out[rr,cc]=2
    else:
        for rr in range(oh):
            for cc in range(ow):
                if A[rr,cc]!=nA and B[bw-1-cc,rr]!=nB: out[rr,cc]=2
    return out.tolist()
