def solve(g):
    g=np.array(g); h,w=g.shape
    cand=[]
    for r in range(h):
        if len(np.unique(g[r,:]))==1: cand.append(('h',r))
    for c in range(w):
        if len(np.unique(g[:,c]))==1: cand.append(('v',c))
    t,k=cand[0]
    A=g[:k] if t=='h' else g[:,:k]
    B=g[k+1:] if t=='h' else g[:,k+1:]
    oh,ow=A.shape; bh,bw=B.shape
    nA=min(Counter(A.flatten().tolist()).items(), key=lambda x:x[1])
    nB=min(Counter(B.flatten().tolist()).items(), key=lambda x:x[1])
    out=np.zeros((oh,ow),int)
    if t=='h':
        for rr in range(oh):
            for cc in range(ow):
                if int(A[rr,cc])!=nA and int(B[bh-1-rr,cc])!=nB: out[rr,cc]=2
    else:
        for rr in range(oh):
            for cc in range(ow):
                if int(A[rr,cc])!=nA and int(B[bw-1-cc,rr])!=nB: out[rr,cc]=2
    return out.tolist()
for i in [1,2,3]:
    print(i, solve(G[f'Demo pair {i} input'])==G[f'Demo pair {i} output'])

