import numpy as np
from collections import Counter
def f(a,b):
    a=np.array(a); b=np.array(b)
    h,w=a.shape
    div=None; kind=None
    for r in range(h):
        if len(np.unique(a[r,:]))==1: div=r; kind='h'
    for c in range(w):
        if len(np.unique(a[:,c]))==1: div=c; kind='v'
    if kind=='h':
        top=a[:div]; bot=a[div+1:]
        oh,ow=top.shape; bh,bw=bot.shape
    else:
        left=a[:,:div]; right=a[:,div+1:]
        ol,or_=left.shape; rh,rw=right.shape
    nt=min(Counter(top.flatten()).items(),key=lambda x:x[1])[0]
    nb=min(Counter(bot.flatten()).items(),key=lambda x:x[1])[0]
    out=np.zeros((oh,ow),int)
    if kind=='h':
        for rr in range(oh):
            for cc in range(ow):
                if top[rr,cc]!=nt and bot[bh-1-rr,cc]!=nb: out[rr,cc]=2
    else:
        for rr in range(ol):
            for cc in range(or_):
                if left[rr,cc]!=nt and right[rh-1-rr,rw-1-cc]!=nb: out[rr,cc]=2
    return out.tolist()
